 graphicsNotice(c,message,x,y,width){c.save();c.font='10px Arial';c.textAlign='left';const lines=[];let current='';for(const word of message.split(' ')){const candidate=current?current+' '+word:word,measure=c.measureText?.(candidate);if((measure?.width??candidate.length*5.2)>width-20&&current){lines.push(current);current=word;}else current=candidate;}if(current)lines.push(current);const shown=lines.slice(0,2);c.fillStyle='#102634f2';c.fillRect(x,y,width,shown.length*14+14);c.fillStyle='#f2f7ed';shown.forEach((line,i)=>c.fillText(line,x+10,y+17+i*14,width-20));c.restore();}
